enviarDuda(){let t=this.duda.trim();if(!t)return;let e=encodeURIComponent("Duda desde la web"),r=encodeURIComponent(t);window.location.href=`mailto:info@soldadosdejuguete.com?subject=${e}&body=${r}`}categorias=[{key:"curiosos",titulo:"Para curiosos",count:6,faqs:[{q:"\xBFQu\xE9 es exactamente el airsoft?",a:"Un deporte de simulaci\xF3n con r\xE9plicas que disparan bolas biodegradables de 6mm. Se juega en equipos con objetivos reales. No es paintball: las bolas no manchan y el juego se basa en el honor (quien recibe un impacto lo reconoce y sale).",open:!0},{q:"\xBFDuele cuando te dan?",a:"Pica, s\xED. Como una goma el\xE1stica fuerte. El 90% no se siente. Con el equipo de protecci\xF3n adecuado (que est\xE1 incluido en el alquiler) es perfectamente tolerable.",open:!1},{q:"\xBFNecesito experiencia para venir?",a:"Cero. La mayor\xEDa de la gente que viene es primera vez. Los monitores explican las reglas, el equipo y la din\xE1mica antes de empezar. En 10 minutos est\xE1s listo.",open:!1},{q:"\xBFEs legal?",a:"S\xED, totalmente regulado. Las r\xE9plicas de airsoft est\xE1n clasificadas como juguetes / deporte. Necesitan seguir la normativa de FPS y edad m\xEDnima, que nosotros cumplimos estrictamente.",open:!1},{q:"\xBFQu\xE9 edad m\xEDnima hay?",a:"Para el campo de airsoft la edad m\xEDnima es a partir de los 14 a\xF1os (los menores necesitan autorizaci\xF3n del tutor). Para los m\xE1s peque\xF1os est\xE1 Txikipaintball, la alternativa familiar, de 8 a 13 a\xF1os.",open:!1},{q:"\xBFEs peligroso?",a:"Es de los deportes m\xE1s seguros: gafas homologadas obligatorias, FPS controlados, monitores siempre presentes. En 16 a\xF1os de campo no hemos tenido ning\xFAn incidente grave.",open:!1}]},{key:"antes",titulo:"Antes de venir",count:5,faqs:[{q:"\xBFQu\xE9 tengo que llevar?",a:"Solo ropa de cambio y calzado deportivo cerrado para la partida. El equipo completo (r\xE9plica, gafas, chaleco, munici\xF3n y uniforme) est\xE1 disponible en alquiler por 20\u20AC extra.",open:!1},{q:"\xBFHay que reservar con antelaci\xF3n?",a:"Para partidas abiertas puedes venir sin reservar, aunque es recomendable para asegurar plaza. Para partidas privadas y eventos, s\xED es necesario contactar antes.",open:!1},{q:"\xBFPuedo llevar mi propia r\xE9plica?",a:"S\xED, si ya tienes equipo propio. La r\xE9plica debe cumplir el l\xEDmite de FPS del campo. La revisamos a la entrada.",open:!1},{q:"\xBFHay parking?",a:"S\xED, parking gratuito con capacidad para 80+ veh\xEDculos directamente en el campo. Hay zona especial para autobuses y furgonetas.",open:!1},{q:"\xBFY si llueve?",a:"Jugamos con lluvia. El barro y el agua forman parte de la experiencia. Solo cancelamos en situaciones de riesgo real (tormenta el\xE9ctrica, alerta meteorol\xF3gica).",open:!1}]},{key:"campo",titulo:"El campo y partidas",count:6,faqs:[{q:"\xBFCu\xE1nto dura una partida?",a:"Una jornada completa dura entre 3 y 4 horas, con varias partidas cortas de 20-30 minutos. Las partidas privadas tienen duraci\xF3n personalizable.",open:!1},{q:"\xBFPuedo ir a ver una partida sin jugar?",a:"S\xED. Hay zonas habilitadas para observadores. Contacta antes para coordinar la visita.",open:!1},{q:"\xBFCu\xE1ntas zonas tiene el campo?",a:"El campo tiene 45.000 m\xB2 con varias zonas diferenciadas: urbana, bosque, colina, bunkers y zona abierta. No todas se usan en cada partida.",open:!1},{q:"\xBFHay vestuarios con duchas?",a:"S\xED. Vestuarios separados (hombre/mujer) con taquillas con llave y duchas calientes. Ba\xF1os accesibles disponibles.",open:!1},{q:"\xBFLlevo gafas graduadas o soy dalt\xF3nico?",a:"Sin problema. Disponemos de protecci\xF3n compatible con gafas graduadas. El daltonismo no afecta al juego: los equipos se distinguen por brazaletes y posici\xF3n, no por color.",open:!1},{q:"\xBFHac\xE9is fotos durante las partidas?",a:"S\xED. Cada semana hacemos fotos de los jugadores durante las partidas y las compartimos en nuestro grupo de Telegram, para que tengas un recuerdo de tu d\xEDa.",link:{url:"https://t.me/sdj_airsoft",label:"Ver las fotos en el grupo de Telegram \u2192"},open:!1}]},{key:"grupos",titulo:"Grupos y familias",count:5,enlace:{url:"/txikipaintball",label:"Ver Txikipaintball (8 a 13 a\xF1os) \u2192",interno:!0},faqs:[{q:"\xBFA partir de cu\xE1ntas personas tenemos campo exclusivo?",a:"A partir de 8 personas ten\xE9is el campo para vosotros solos, con monitor incluido y sin coste extra por la partida privada (solo pag\xE1is las tarifas individuales de cada jugador).",open:!1},{q:"\xBFHac\xE9is despedidas de soltero/a?",a:'S\xED, y son de las m\xE1s \xE9picas. Tenemos un modo especial "novix objetivo". Consulta el pack de despedidas en la p\xE1gina de Eventos.',open:!1},{q:"\xBFHac\xE9is team building para empresas?",a:"S\xED. Actividad de cohesi\xF3n sin powerpoints. Podemos adaptar los objetivos y modos de juego a lo que busca el equipo. Pide m\xE1s info en Eventos.",open:!1},{q:"\xBFPodemos venir con ni\xF1os peque\xF1os?",a:"S\xED. Para los peques de 8 a 13 a\xF1os tenemos Txikipaintball, la versi\xF3n familiar con bolas de baja potencia, monitor y todo el material incluido. Es la opci\xF3n ideal para cumplea\xF1os y planes en familia.",open:!1},{q:"\xBFY para colectivos?",a:"S\xED, con supervisi\xF3n y seguridad reforzada. El airsoft es una actividad deportiva reconocida. Contacta para los requisitos concretos seg\xFAn la edad del grupo.",open:!1}]},{key:"pago",titulo:"Pago y cancelaci\xF3n",count:4,faqs:[{q:"\xBFC\xF3mo se paga?",a:"En el campo el d\xEDa de la partida (efectivo o tarjeta). Para eventos privados puede requerirse una se\xF1al previa para confirmar la reserva.",open:!1},{q:"\xBFPuedo cancelar?",a:"Cancelaci\xF3n gratuita hasta 48h antes. Pasado ese plazo, si ya hay se\xF1al pagada, puede retenerse una parte seg\xFAn el caso.",open:!1},{q:"\xBFQu\xE9 pasa si no aparezco sin avisar?",a:"La plaza se libera para otros jugadores. Si ya hab\xEDas pagado se\xF1al, no se devuelve.",open:!1},{q:"\xBFQu\xE9 pasa si llueve y se cancela?",a:"Solo cancelamos en situaciones de riesgo real. Si la cancelaci\xF3n es por nuestra parte, se reembolsa \xEDntegramente o se reagenda sin coste.",open:!1}]}];categoriaData=J(()=>this.categorias.find(t=>t.key===this.categoriaActiva())??this.categorias[0]);seo=S(X);constructor(){this.seo.setJsonLd("faq",{"@context":"https://schema.org","@type":"FAQPage",mainEntity:this.categorias.flatMap(t=>t.faqs).map(t=>({"@type":"Question",name:t.q,acceptedAnswer:{"@type":"Answer",text:t.a}}))},"/faq")}get todasFaqs(){return this.categorias.flatMap(t=>t.faqs.map(e=>N(j({},e),{cat:t.titulo})))}normalizar(t){return t.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[¿?¡!]/g,"")}levenshtein(t,e){let r=t.length,l=e.length,c=Array.from({length:r+1},(g,_)=>Array.from({length:l+1},(w,E)=>_===0?E:E===0?_:0));for(let g=1;g<=r;g++)for(let _=1;_<=l;_++)c[g][_]=t[g-1]===e[_-1]?c[g-1][_-1]:1+Math.min(c[g-1][_],c[g][_-1],c[g-1][_-1]);return c[r][l]}tolerancia(t){return t<=3?0:t<=6?1:2}coincidePalabra(t,e){return e.includes(t)?!0:t.length<=2?!1:this.levenshtein(t,e)<=this.tolerancia(t.length)}coincideFuzzy(t,e){return e.includes(t)?!0:t.length<=2?!1:e.split(/\s+/).some(r=>this.coincidePalabra(t,r))}expandirTerminos(t){let r=this.normalizar(t).split(/\s+/).filter(c=>c.length>1),l=[];for(let[c,g]of Object.entries(Oe)){let _=this.normalizar(c),w=g.map(P=>this.normalizar(P));r.some(P=>this.coincidePalabra(P,_)||w.some(te=>te.split(/\s+/).some(ne=>this.coincidePalabra(P,ne))))&&l.push(_,...w)}return[...new Set([...r,...l])]}get resultados(){let t=this.busqueda.trim();if(t.length<2)return[];let e=this.expandirTerminos(t);return this.todasFaqs.filter(r=>{let l=this.normalizar(r.q+" "+r.a);return e.some(c=>this.coincideFuzzy(c,l))})}get sugerencias(){let t=this.busqueda.trim();if(t.length<2)return[];let r=this.normalizar(t).split(/\s+/).filter(l=>l.length>1);return this.todasFaqs.filter(l=>r.some(c=>this.coincideFuzzy(c,this.normalizar(l.q)))).map(l=>l.q).slice(0,4)}searchTimer;onBus